[
  {
    "question": "What is the primary purpose of a data structure in computer science?",
    "options": {
      "A": "To store and organize data efficiently",
      "B": "To perform arithmetic calculations",
      "C": "To compile source code",
      "D": "To manage network communication"
    },
    "correct_answer": "A",
    "explanation": "Data structures are designed to store and organize data so that it can be accessed and manipulated efficiently; the other options describe unrelated tasks.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following data structures stores its elements in a contiguous block of memory?",
    "options": {
      "A": "Linked list",
      "B": "Binary tree",
      "C": "Array",
      "D": "Adjacency‑list graph"
    },
    "correct_answer": "C",
    "explanation": "An array allocates a single continuous memory region for all its elements, whereas linked lists, trees, and adjacency lists use scattered nodes linked by pointers.",
    "difficulty": "Medium"
  },
  {
    "question": "In the context of data structures, which term describes a structure whose size can change during program execution?",
    "options": {
      "A": "Static",
      "B": "Fixed",
      "C": "Dynamic",
      "D": "Immutable"
    },
    "correct_answer": "C",
    "explanation": "Dynamic data structures (e.g., linked lists, dynamic arrays) can grow or shrink at runtime, unlike static or fixed structures whose size is set at compile time.",
    "difficulty": "Medium"
  },
  {
    "question": "Which basic operation is common to both stacks and queues?",
    "options": {
      "A": "Viewing the element at the front/top without removing it",
      "B": "Random access by index",
      "C": "Sorting all stored elements",
      "D": "Merging two separate structures"
    },
    "correct_answer": "A",
    "explanation": "Both stacks (peek) and queues (front) provide an operation to look at the next element to be removed without actually removing it; the other operations are not fundamental to both.",
    "difficulty": "Medium"
  },
  {
    "question": "Which data structure allows O(1) insertion and deletion at both the front and rear ends?",
    "options": {
      "A": "Stack",
      "B": "Queue",
      "C": "Deque",
      "D": "Binary search tree"
    },
    "correct_answer": "C",
    "explanation": "A deque (double‑ended queue) supports constant‑time insertion and deletion at both ends, while a stack works at one end, a queue at opposite ends, and a BST requires O(log n) operations.",
    "difficulty": "Medium"
  }
]
